 var existing by remember{mutableStateOf(true)};var name by remember{mutableStateOf("")};var lender by remember{mutableStateOf("")};var principal by remember{mutableStateOf("")};var account by remember{mutableStateOf("")};var hasInterest by remember{mutableStateOf(true)};var mode by remember{mutableStateOf("principal_interest")};var payment by remember{mutableStateOf("")};var totalPeriods by remember{mutableStateOf("")};var firstDue by remember{mutableStateOf(LocalDate.now(VietnamZone).plusMonths(1).toString())};var principalDue by remember{mutableStateOf("")};var currentPeriodPaid by remember{mutableStateOf(false)};var note by remember{mutableStateOf("")};var validation by remember{mutableStateOf<String?>(null)}
